import{_ as t,o as a,c as n,a0 as r}from"./chunks/framework.ysVzM4be.js";const u=JSON.parse('{"title":"Commands","description":"The npm commands of the repository, the shared control gallery, and the contained mutation testing.","frontmatter":{"title":"Commands","description":"The npm commands of the repository, the shared control gallery, and the contained mutation testing."},"headers":[],"relativePath":"getting-started/commands.md","filePath":"getting-started/commands.md"}'),o={name:"getting-started/commands.md"};function d(s,e,c,h,i,l){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>npm run dev</code></td><td>Start the control plane in watch mode</td></tr><tr><td><code>npm test</code></td><td>Run the full test suite</td></tr><tr><td><code>npm run gallery</code></td><td>Run the shared control gallery, using the real modules</td></tr><tr><td><code>npm run mutate</code></td><td>Run Stryker mutation testing, contained</td></tr><tr><td><code>npm run lint</code></td><td>Lint and check formatting with Biome</td></tr><tr><td><code>npm run fmt</code></td><td>Lint, format, and fix with Biome</td></tr><tr><td><code>npm run typecheck</code></td><td>Typecheck with TypeScript</td></tr><tr><td><code>npm run screenshots</code></td><td>Regenerate the guide screenshots from fixture state</td></tr></tbody></table><p><code>npm run dev</code> runs the source tree; it reads <code>config/development.toml</code> through <code>--config</code> and watches the tree while it runs.</p><h2 id="shared-control-gallery" tabindex="-1">Shared control gallery <a class="header-anchor" href="#shared-control-gallery" aria-label="Permalink to &quot;Shared control gallery&quot;">​</a></h2><p><code>npm run gallery</code> opens the shared control gallery: every control the control plane owns, drawn by the production modules and answering the production keys. <code>Tab</code> shows the next example, and each one names its own state - normal and focused, invalid, unavailable, loading, Type-ahead search, and narrow. Pass an example name to land on it: <code>npm run gallery -- fields</code>. The gallery reads no config file, opens no state, and starts no Agent, and the same examples are exercised by <code>npm test</code>, so a gallery row cannot become an imitation of the control. See <a href="./../shared-controls.html">the shared control standard</a>.</p><h2 id="mutation-testing" tabindex="-1">Mutation testing <a class="header-anchor" href="#mutation-testing" aria-label="Permalink to &quot;Mutation testing&quot;">​</a></h2><p><code>npm run mutate</code> runs Stryker through the crash guard (<code>scripts/crash-guard.sh</code>). The suite spawns control plane processes, and a native crash in the runner (the known case is the node:sqlite use-after-free in node 26.5.0) would otherwise leave them orphaned under systemd and write a core file for every death. The guard contains both: it runs the whole process tree with core files disabled, so the OS records no crash, and when Stryker exits, by success, failure, or crash, the guard terminates every surviving process of the run. Extra arguments pass through to Stryker, such as <code>npm run mutate -- --dryRunOnly</code>.</p><h2 id="regenerating-the-screenshots" tabindex="-1">Regenerating the screenshots <a class="header-anchor" href="#regenerating-the-screenshots" aria-label="Permalink to &quot;Regenerating the screenshots&quot;">​</a></h2><p><code>npm run screenshots</code> rebuilds the images the <a href="./../operation/main-view.html">operation guide</a> shows: the fixture world, the production binary on a pseudo-terminal, the production keys, and the cell-grid render. The drift test in <code>npm test</code> reruns the same path and fails when a committed image no longer matches the screen, so a screen change always lands with its image.</p>',9)])])}const p=t(o,[["render",d]]);export{u as __pageData,p as default};
